(function() {
    'use strict';

    class DigitalHotelAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Digital Hotel: Technology Transformation';
            this.version = '1.0.0';
            this.YEAR_BUDGETS = [150000, 150000, 120000];
            this.BREACH_ANNUAL_COST = 71500;
            this.INVESTMENTS = [
                { id: 1, nameKey: 'inv_pms', cost: 80000, annualROI: 80000, totalROI: 240000, risk: 'medium', prereqs: [], complex: true, maturityPts: 2, alignPts: 10, groups: ['operations', 'finance'] },
                { id: 2, nameKey: 'inv_channel', cost: 25000, annualROI: 16667, totalROI: 50000, risk: 'low', prereqs: [], complex: false, maturityPts: 1, alignPts: 8, groups: ['revenue'] },
                { id: 3, nameKey: 'inv_direct', cost: 45000, annualROI: 60000, totalROI: 180000, risk: 'medium', prereqs: [1], complex: false, maturityPts: 1, alignPts: 12, groups: ['marketing', 'guest_exp'] },
                { id: 4, nameKey: 'inv_crm', cost: 55000, annualROI: 53333, totalROI: 160000, risk: 'medium', prereqs: [1], complex: true, maturityPts: 1, alignPts: 10, groups: ['marketing', 'guest_exp'] },
                { id: 5, nameKey: 'inv_dynamic', cost: 35000, annualROI: 66667, totalROI: 200000, risk: 'high', prereqs: [1], complex: true, maturityPts: 1, alignPts: 8, groups: ['revenue'] },
                { id: 6, nameKey: 'inv_rms', cost: 65000, annualROI: 83333, totalROI: 250000, risk: 'high', prereqs: [1], complex: true, maturityPts: 2, alignPts: 10, groups: ['revenue'] },
                { id: 7, nameKey: 'inv_housekeeping', cost: 20000, annualROI: 26667, totalROI: 80000, risk: 'low', prereqs: [], complex: false, maturityPts: 1, alignPts: 5, groups: ['operations', 'housekeeping'] },
                { id: 8, nameKey: 'inv_pos', cost: 20000, annualROI: 16667, totalROI: 50000, risk: 'low', prereqs: [], complex: false, maturityPts: 0, alignPts: 4, groups: ['finance', 'fb'] },
                { id: 9, nameKey: 'inv_ai', cost: 65000, annualROI: 100000, totalROI: 300000, risk: 'high', prereqs: [6], complex: true, maturityPts: 2, alignPts: 8, groups: ['revenue'] },
                { id: 10, nameKey: 'inv_training', cost: 15000, annualROI: 33333, totalROI: 100000, risk: 'low', prereqs: [], complex: false, maturityPts: 1, alignPts: 7, groups: ['hr'] },
                { id: 11, nameKey: 'inv_cyber', cost: 50000, annualROI: 99258, totalROI: 297000, risk: 'medium', prereqs: [], complex: false, maturityPts: 1, alignPts: 12, groups: ['security'] },
                { id: 12, nameKey: 'inv_cloud', cost: 30000, annualROI: 33333, totalROI: 100000, risk: 'high', prereqs: [1, 11], complex: true, maturityPts: 2, alignPts: 6, groups: ['it'] }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    purchased: [],
                    yearPurchases: [],
                    cumulativeROI: 0,
                    cumulativeInvestment: 0,
                    netValue: 0,
                    maturityLevel: 2,
                    roiHistory: [],
                    netValueHistory: [],
                    scoreHistory: [],
                    financialScore: 0,
                    strategicScore: 0,
                    riskScore: 0,
                    maturityScore: 0,
                    stakeholderScore: 0,
                    overallScore: 0
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    selectedIds: [],
                    yearCost: 0
                };
            }
            this._renderInvestments(state);
            this._updateBriefing(state);
            this._updateScorecard(state.domainState);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var grid = document.getElementById('investmentGrid');
            var selected = [];
            var totalCost = 0;
            var self = this;

            if (grid) {
                var checks = grid.querySelectorAll('.dighotel-inv-check:checked:not(:disabled)');
                for (var i = 0; i < checks.length; i++) {
                    var invId = parseInt(checks[i].value);
                    var inv = self._findInv(invId);
                    if (inv) {
                        selected.push(invId);
                        totalCost += inv.cost;
                    }
                }
            }

            var yearIdx = Math.min((state.currentPeriod || 1) - 1, 2);
            var yearBudget = this.YEAR_BUDGETS[yearIdx];

            if (totalCost > yearBudget) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }

            decisions.selectedIds = selected;
            decisions.yearCost = totalCost;
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var self = this;

            var newPurchases = d.selectedIds || [];
            for (var i = 0; i < newPurchases.length; i++) {
                if (ds.purchased.indexOf(newPurchases[i]) === -1) {
                    ds.purchased.push(newPurchases[i]);
                }
            }
            ds.yearPurchases.push(newPurchases.slice());

            ds.cumulativeInvestment += (d.yearCost || 0);

            var annualROI = this._calculateAnnualROI(ds);

            ds.cumulativeROI += annualROI;
            ds.netValue = ds.cumulativeROI - ds.cumulativeInvestment;

            var matPts = 0;
            for (var j = 0; j < ds.purchased.length; j++) {
                var inv = self._findInv(ds.purchased[j]);
                if (inv) matPts += inv.maturityPts;
            }
            ds.maturityLevel = Math.min(5, 2 + Math.floor(matPts * 3 / 15));

            this._calculateScores(ds);

            ds.roiHistory.push(annualROI);
            ds.netValueHistory.push(ds.netValue);
            ds.scoreHistory.push(ds.overallScore);

            var self2 = this;
            setTimeout(function() {
                self2._renderInvestments(window.mySimulation.state);
                self2._updateBriefing(window.mySimulation.state);
                self2._updateScorecard(window.mySimulation.state.domainState);
            }, 300);

            return {
                period: state.currentPeriod,
                yearCost: d.yearCost || 0,
                annualROI: annualROI,
                netValue: ds.netValue,
                maturityLevel: ds.maturityLevel,
                overallScore: ds.overallScore
            };
        }

        _findInv(id) {
            for (var i = 0; i < this.INVESTMENTS.length; i++) {
                if (this.INVESTMENTS[i].id === id) return this.INVESTMENTS[i];
            }
            return null;
        }

        _calculateAnnualROI(ds) {
            var self = this;
            var purchased = ds.purchased;
            var hasTraining = purchased.indexOf(10) !== -1;
            var hasCyber = purchased.indexOf(11) !== -1;
            var total = 0;

            for (var i = 0; i < purchased.length; i++) {
                var inv = self._findInv(purchased[i]);
                if (!inv) continue;

                var roi = inv.annualROI;

                var prereqsMet = true;
                for (var p = 0; p < inv.prereqs.length; p++) {
                    if (purchased.indexOf(inv.prereqs[p]) === -1) {
                        prereqsMet = false;
                        break;
                    }
                }
                if (!prereqsMet) roi *= 0.5;

                if (inv.id !== 11) {
                    if (inv.complex) {
                        roi *= hasTraining ? 0.85 : 0.50;
                    } else {
                        roi *= hasTraining ? 0.95 : 0.70;
                    }
                }

                if (inv.id === 3 && purchased.indexOf(4) !== -1) roi *= 1.20;
                if (inv.id === 4 && purchased.indexOf(3) !== -1) roi *= 1.20;
                if (inv.id === 5 && purchased.indexOf(6) !== -1) roi *= 1.25;
                if (inv.id === 6 && purchased.indexOf(5) !== -1) roi *= 1.25;

                total += roi;
            }

            if (!hasCyber) total -= 71500;

            return Math.round(total);
        }

        _calculateScores(ds) {
            var self = this;
            var purchased = ds.purchased;

            var maxNetValue = 800000;
            ds.financialScore = Math.min(100, Math.max(0, Math.round((ds.netValue / maxNetValue) * 100)));

            var totalAlignPts = 0;
            for (var i = 0; i < purchased.length; i++) {
                var inv = self._findInv(purchased[i]);
                if (inv) totalAlignPts += inv.alignPts;
            }
            ds.strategicScore = Math.min(100, totalAlignPts);

            var riskScore = 30;
            if (purchased.indexOf(11) !== -1) riskScore += 30;
            if (purchased.indexOf(10) !== -1) riskScore += 20;
            var highRiskIds = [5, 6, 9, 12];
            for (var h = 0; h < highRiskIds.length; h++) {
                var hid = highRiskIds[h];
                if (purchased.indexOf(hid) !== -1) {
                    var hInv = self._findInv(hid);
                    if (hInv) {
                        var hPrereqsMet = true;
                        for (var hp = 0; hp < hInv.prereqs.length; hp++) {
                            if (purchased.indexOf(hInv.prereqs[hp]) === -1) {
                                hPrereqsMet = false;
                                break;
                            }
                        }
                        if (!hPrereqsMet) riskScore -= 15;
                    }
                }
            }
            var yearsUsed = 0;
            for (var y = 0; y < (ds.yearPurchases || []).length; y++) {
                if (ds.yearPurchases[y] && ds.yearPurchases[y].length > 0) yearsUsed++;
            }
            if (yearsUsed >= 2) riskScore += 5;
            if (yearsUsed >= 3) riskScore += 5;
            ds.riskScore = Math.min(100, Math.max(0, riskScore));

            ds.maturityScore = Math.round(((ds.maturityLevel - 2) / 3) * 100);

            var allGroups = [];
            for (var s = 0; s < purchased.length; s++) {
                var sInv = self._findInv(purchased[s]);
                if (sInv && sInv.groups) {
                    for (var g = 0; g < sInv.groups.length; g++) {
                        if (allGroups.indexOf(sInv.groups[g]) === -1) allGroups.push(sInv.groups[g]);
                    }
                }
            }
            ds.stakeholderScore = Math.min(100, Math.round((allGroups.length / 8) * 100));

            ds.overallScore = Math.round(
                ds.financialScore * 0.35 +
                ds.strategicScore * 0.25 +
                ds.riskScore * 0.20 +
                ds.maturityScore * 0.15 +
                ds.stakeholderScore * 0.05
            );
        }

        _renderInvestments(state) {
            var grid = document.getElementById('investmentGrid');
            if (!grid) return;

            var purchased = state.domainState ? state.domainState.purchased : [];
            var yearIdx = Math.min((state.currentPeriod || 1) - 1, 2);
            var yearBudget = this.YEAR_BUDGETS[yearIdx];
            var html = '';
            var self = this;
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            for (var i = 0; i < this.INVESTMENTS.length; i++) {
                var inv = this.INVESTMENTS[i];
                var isPurchased = purchased.indexOf(inv.id) !== -1;
                var cardClass = isPurchased ? ' dighotel-purchased' : '';
                var disabledAttr = isPurchased ? ' disabled checked' : '';

                var prereqStatus = '';
                if (inv.prereqs.length > 0) {
                    var prereqNames = [];
                    var allMet = true;
                    for (var p = 0; p < inv.prereqs.length; p++) {
                        var pInv = self._findInv(inv.prereqs[p]);
                        if (pInv) prereqNames.push(t(pInv.nameKey));
                        if (purchased.indexOf(inv.prereqs[p]) === -1) allMet = false;
                    }
                    var prereqClass = allMet ? 'dighotel-prereq-met' : 'dighotel-prereq-unmet';
                    var prereqIcon = allMet ? '\u2713' : '\u26A0';
                    prereqStatus = '<span class="' + prereqClass + '">' + prereqIcon + ' ' + t('prereqs_label') + ': ' + prereqNames.join(', ') + '</span>';
                }

                var riskClass = 'dighotel-risk-' + inv.risk;
                var riskLabel = t('risk_' + inv.risk);

                html += '<div class="dighotel-sim-inv-card' + cardClass + '">';
                html += '<label>';
                html += '<input type="checkbox" class="dighotel-inv-check" value="' + inv.id + '"' + disabledAttr + '>';
                html += '<div class="dighotel-inv-info">';
                html += '<span class="dighotel-inv-name">' + t(inv.nameKey) + '</span>';
                html += '<span class="dighotel-inv-detail">' + t('cost_label') + ': $' + inv.cost.toLocaleString() + ' | ' + t('roi_3yr') + ': $' + inv.totalROI.toLocaleString() + '</span>';
                html += '<div class="dighotel-inv-badges">';
                html += '<span class="dighotel-badge ' + riskClass + '">' + riskLabel + '</span>';
                if (isPurchased) html += '<span class="dighotel-purchased-tag">' + t('purchased_badge') + '</span>';
                html += '</div>';
                if (prereqStatus) html += prereqStatus;
                html += '</div></label></div>';
            }

            grid.innerHTML = html;

            var checks = grid.querySelectorAll('.dighotel-inv-check:not(:disabled)');
            var costDisplay = document.getElementById('selectedCostDisplay');
            for (var c = 0; c < checks.length; c++) {
                checks[c].addEventListener('change', function() {
                    var totalSelected = 0;
                    var allChecked = grid.querySelectorAll('.dighotel-inv-check:checked:not(:disabled)');
                    for (var ac = 0; ac < allChecked.length; ac++) {
                        var cInv = self._findInv(parseInt(allChecked[ac].value));
                        if (cInv) totalSelected += cInv.cost;
                    }
                    if (costDisplay) costDisplay.textContent = '$' + totalSelected.toLocaleString();
                    var card = this.closest('.dighotel-sim-inv-card');
                    if (card) {
                        if (this.checked) {
                            card.classList.add('dighotel-checked');
                        } else {
                            card.classList.remove('dighotel-checked');
                        }
                    }
                });
            }

            var availDisplay = document.getElementById('availableBudgetDisplay');
            if (availDisplay) availDisplay.textContent = '$' + yearBudget.toLocaleString();

            if (costDisplay) costDisplay.textContent = '$0';
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, 2);
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var briefKeys = ['briefing_y1', 'briefing_y2', 'briefing_y3'];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(briefKeys[idx]);

            var yearBudget = this.YEAR_BUDGETS[idx];
            var yearBudgetEl = document.getElementById('yearBudgetDisplay');
            if (yearBudgetEl) yearBudgetEl.textContent = '$' + yearBudget.toLocaleString();

            var ds = state.domainState || {};
            var totalRemaining = 420000 - (ds.cumulativeInvestment || 0);
            var totalBudgetEl = document.getElementById('totalBudgetDisplay');
            if (totalBudgetEl) totalBudgetEl.textContent = '$' + totalRemaining.toLocaleString();

            var netValueEl = document.getElementById('netValueDisplay');
            if (netValueEl) {
                var nv = ds.netValue || 0;
                netValueEl.textContent = (nv < 0 ? '-$' + Math.abs(nv).toLocaleString() : '$' + nv.toLocaleString());
            }

            var matEl = document.getElementById('maturityDisplay');
            if (matEl) matEl.textContent = t('level_prefix') + (ds.maturityLevel || 2);

            var scoreEl = document.getElementById('scoreDisplay');
            if (scoreEl) scoreEl.textContent = (ds.overallScore || 0);
        }

        _updateScorecard(ds) {
            var barsEl = document.getElementById('scorecardBars');
            if (!barsEl) return;
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var dims = [
                { key: 'financial_dim', score: ds.financialScore || 0, weight: '35%', color: '#27ae60' },
                { key: 'strategic_dim', score: ds.strategicScore || 0, weight: '25%', color: '#2980b9' },
                { key: 'risk_dim', score: ds.riskScore || 0, weight: '20%', color: '#e67e22' },
                { key: 'maturity_dim', score: ds.maturityScore || 0, weight: '15%', color: '#8e44ad' },
